<?php

declare(strict_types=1);

$companyId = max(0, (int) ($_GET['empresa_id'] ?? 0));
$page = max(1, (int) ($_GET['page'] ?? 1));
$filters = [
    'search' => trim((string) ($_GET['q'] ?? '')),
    'status' => trim((string) ($_GET['status'] ?? '')),
    'origin' => trim((string) ($_GET['origem'] ?? '')),
    'date_from' => trim((string) ($_GET['data_inicial'] ?? '')),
    'date_to' => trim((string) ($_GET['data_final'] ?? '')),
];
if ($filters['date_from'] === '' && $filters['date_to'] === '') {
    $month = max(1, min(12, (int) ($_GET['mes'] ?? date('n'))));
    $year = max(2000, min(2100, (int) ($_GET['ano'] ?? date('Y'))));
    $filters['date_from'] = sprintf('%04d-%02d-01', $year, $month);
    $filters['date_to'] = date('Y-m-t', strtotime($filters['date_from']));
}
$data = null; $loadError = null; $detail = null;
$clients = [];
try {
    $data = $application->soAcquisitionBrowser()->browse($companyId, $filters, $page, 20);
    $detailId = max(0, (int) ($_GET['detalhe'] ?? 0));
    if ($detailId > 0) $detail = $application->soAcquisitionBrowser()->details($companyId, $detailId);
} catch (InvalidArgumentException $exception) { $loadError = $exception->getMessage(); }
catch (Throwable $exception) { error_log('SO acquisition browser failed: ' . $exception::class); $loadError = 'Não foi possível carregar as aquisições agora.'; }
$statement = $application->database()->connection()->prepare('SELECT id, nome, codigo FROM clientes WHERE empresa_id = :empresa_id AND excluido_em IS NULL ORDER BY nome LIMIT 200');
$statement->execute(['empresa_id' => $companyId]); $clients = $statement->fetchAll();
if ($clients === []) {
    $clients[] = ['id' => 0, 'codigo' => '', 'nome' => 'Prefeitura (será cadastrada automaticamente)'];
}

$adminContent = static function () use ($data, $detail, $loadError, $filters, $companyId, $page, $clients, $csrf): void {
    if ($loadError !== null) { admin_empty('Consulta indisponível', $loadError); return; }
    $company = $data['company']; $supplier = $data['supplier']; $result = $data['result']; $summary = $result['summary'];
    $name = $company['nome_fantasia'] ?: $company['razao_social'];
    ?>
    <section class="admin-panel">
        <div class="admin-detail-header"><div><h2><?= admin_h($name) ?></h2><p><?= admin_h($company['documento'] ?? '—') ?> · <?= admin_h($company['segmento'] ?? '—') ?><br>Fornecedor SO: <?= admin_h($supplier['nome']) ?> · <?= admin_h($supplier['cnpj'] ?: 'CNPJ não informado') ?></p></div><div><a class="btn btn-outline-secondary" href="<?= admin_url('empresas.php') ?>">Voltar para empresas</a><a class="btn btn-primary" href="<?= admin_url('empresa.php?id=' . $companyId) ?>">Entrar no painel da empresa</a></div></div>
        <div class="admin-metrics"><div><span>Total de aquisições</span><strong><?= (int) ($summary['total'] ?? 0) ?></strong></div><div><span>Valor total</span><strong>R$ <?= number_format((float) ($summary['valor_total'] ?? 0), 2, ',', '.') ?></strong></div><div><span>Aguardando entrega</span><strong><?= (int) ($summary['aguardando_entrega'] ?? 0) ?></strong></div><div><span>Finalizadas</span><strong><?= (int) ($summary['finalizadas'] ?? 0) ?></strong></div><div><span>Última aquisição</span><strong><?= admin_h($summary['ultima_aquisicao'] ?? '—') ?></strong></div></div>
        <form method="get" class="admin-filters"><input type="hidden" name="empresa_id" value="<?= $companyId ?>"><input name="q" value="<?= admin_h($filters['search']) ?>" placeholder="Aquisição, entrega, ofício, item ou secretaria"><select name="status"><option value="">Todos os status</option><?php foreach (['pendente','em_andamento','finalizada','cancelada'] as $status): ?><option value="<?= $status ?>" <?= $filters['status'] === $status ? 'selected' : '' ?>><?= admin_h(ucfirst(str_replace('_', ' ', $status))) ?></option><?php endforeach; ?></select><select name="origem"><option value="">Todas as origens</option><option value="so" <?= $filters['origin'] === 'so' ? 'selected' : '' ?>>SO</option><option value="flux" <?= $filters['origin'] === 'flux' ? 'selected' : '' ?>>Flux Empresas</option></select><input type="date" name="data_inicial" value="<?= admin_h($filters['date_from']) ?>"><input type="date" name="data_final" value="<?= admin_h($filters['date_to']) ?>"><button class="btn btn-primary">Filtrar</button><a class="btn btn-outline-secondary" href="<?= admin_url('empresa-aquisicoes.php?empresa_id=' . $companyId) ?>">Limpar</a></form>
        <div class="table-responsive"><table class="table os-table"><thead><tr><th>Aquisição</th><th>Ofício</th><th>Secretaria</th><th>Itens</th><th>Data</th><th>Valor</th><th>Status</th><th>Origem</th><th>Integração</th><th>Ações</th></tr></thead><tbody><?php foreach ($result['items'] as $row): $integration = $row['integration']; ?><tr><td><?= admin_h($row['numero_aq']) ?><br><small><?= admin_h($row['codigo_entrega'] ?: '—') ?></small></td><td><?= admin_h($row['oficio_numero'] ?: '—') ?></td><td><?= admin_h($row['secretaria_nome'] ?: '—') ?></td><td><?= (int) $row['itens_total'] ?></td><td><?= admin_h($row['data_finalizacao'] ?: $row['criado_em']) ?></td><td>R$ <?= number_format((float) $row['valor_total'], 2, ',', '.') ?></td><td><?= admin_h($row['status']) ?></td><td><?= admin_h($row['origem']) ?></td><td><?= admin_h($integration['status_integracao'] ?? 'Não importada') ?></td><td><a class="btn btn-sm btn-outline-primary" href="<?= admin_url('empresa-aquisicoes.php?' . http_build_query(['empresa_id' => $companyId, 'detalhe' => $row['id']])) ?>">Ver detalhes</a><?php if (($integration['ordem_servico_id'] ?? null) === null): ?><button class="btn btn-sm btn-primary" type="button" data-bs-toggle="modal" data-bs-target="#criar-os-<?= (int) $row['id'] ?>"><i class="bi bi-plus-circle"></i> Importar para OS</button><div class="modal fade" id="criar-os-<?= (int) $row['id'] ?>" tabindex="-1" aria-labelledby="criar-os-titulo-<?= (int) $row['id'] ?>" aria-hidden="true"><div class="modal-dialog"><form method="post" action="<?= admin_url('actions/empresa-aquisicao-criar-os.php') ?>" class="modal-content"><?= $csrf->field() ?><input type="hidden" name="empresa_id" value="<?= $companyId ?>"><input type="hidden" name="aquisicao_id" value="<?= (int) $row['id'] ?>"><div class="modal-header"><h2 class="modal-title fs-5" id="criar-os-titulo-<?= (int) $row['id'] ?>">Importar aquisição <?= admin_h($row['numero_aq']) ?> para OS</h2><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Fechar"></button></div><div class="modal-body"><?php if ($clients === []): ?><div class="alert alert-warning" role="alert">Não há clientes cadastrados nesta empresa. Cadastre um cliente antes de importar a aquisição.</div><?php else: ?><label class="form-label">Cliente<select class="form-select" name="cliente_id" required><option value="">Selecione</option><?php foreach ($clients as $client): ?><option value="<?= (int) $client['id'] ?>"><?= admin_h(($client['codigo'] ?? '') . ' · ' . $client['nome']) ?></option><?php endforeach; ?></select></label><label class="form-label">Prioridade<select class="form-select" name="prioridade"><option value="media">Média</option><option value="baixa">Baixa</option><option value="alta">Alta</option><option value="urgente">Urgente</option></select></label><label class="form-label">Observação<textarea class="form-control" name="observacao" maxlength="2000"></textarea></label><?php endif; ?><p class="small">Secretaria sugerida: <?= admin_h($row['secretaria_nome'] ?: '—') ?></p></div><div class="modal-footer"><button type="button" class="btn btn-outline-secondary" data-bs-dismiss="modal">Cancelar</button><button class="btn btn-primary" type="submit" <?= $clients === [] ? 'disabled aria-disabled="true"' : '' ?>>Importar para ordem de serviço</button></div></form></div></div><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div>
        <?php admin_pagination($page, (int) $result['total'], 20, 'empresa-aquisicoes.php', ['empresa_id' => $companyId, 'q' => $filters['search'], 'status' => $filters['status'], 'origem' => $filters['origin'], 'data_inicial' => $filters['date_from'], 'data_final' => $filters['date_to']]); ?>
    </section>
    <?php if ($detail !== null): $a = $detail['acquisition']; ?><section class="admin-panel"><div class="admin-detail-header"><h2>Aquisição <?= admin_h($a['numero_aq']) ?></h2><a class="btn btn-outline-secondary" href="<?= admin_url('empresa-aquisicoes.php?empresa_id=' . $companyId) ?>">Fechar detalhes</a></div><p>Entrega: <?= admin_h($a['codigo_entrega'] ?: '—') ?> · Fornecedor: <?= admin_h($a['fornecedor_nome']) ?> · Secretaria: <?= admin_h($a['secretaria_nome'] ?: '—') ?> · Ofício: <?= admin_h($a['oficio_numero'] ?: '—') ?></p><p>Local: <?= admin_h($a['oficio_local'] ?: '—') ?><br>Justificativa: <?= admin_h($a['oficio_justificativa'] ?: '—') ?></p><table class="table"><thead><tr><th>Item</th><th>Quantidade</th><th>Valor unitário</th><th>Subtotal</th></tr></thead><tbody><?php foreach ($detail['items'] as $item): ?><tr><td><?= admin_h($item['produto']) ?></td><td><?= admin_h($item['quantidade']) ?></td><td>R$ <?= number_format((float) $item['valor_unitario'], 2, ',', '.') ?></td><td>R$ <?= number_format((float) $item['quantidade'] * (float) $item['valor_unitario'], 2, ',', '.') ?></td></tr><?php endforeach; ?></tbody></table><strong>Total: R$ <?= number_format((float) $a['valor_total'], 2, ',', '.') ?></strong></section><?php endif;
};
